    "slug": "what-is-ipm-integrated-pest-management-explained",
    "title": "What Is IPM? Integrated Pest Management Explained",
    "date": "January 31, 2026",
    "dateISO": "2026-01-31",
    "category": "Blog",
    "pestCategory": "Rodents",
